function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listPn1ServiceInvoices(
  query: Record<string, string | number | boolean>,
): Promise<Pn1ServiceInvoiceListItem[]> {
  const res = await apiClient.get<BffResponse<Pn1ServiceInvoiceListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getPn1ServiceInvoice(sttRec: string): Promise<Pn1ServiceInvoice> {
  const res = await apiClient.get<BffResponse<Pn1ServiceInvoice>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createPn1ServiceInvoice(body: Pn1ServiceInvoiceWrite): Promise<Pn1ServiceInvoice> {
  const res = await apiClient.post<BffResponse<Pn1ServiceInvoice>>(BASE, body);
  return unwrap(res);
}

export async function updatePn1ServiceInvoice(sttRec: string, body: Pn1ServiceInvoiceWrite): Promise<Pn1ServiceInvoice> {
  const res = await apiClient.put<BffResponse<Pn1ServiceInvoice>>(`${BASE}/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}
